import {CODES,SEQUESTRATION,MEDICARE_SHARE,modifierIncrement,CF_2026_WITHOUT_ONE_YEAR_INCREASE,APCM_CODES,APCM_START,apcmFee} from './engine.mjs';
// Each policy event: a one-sentence summary, one or more "what changed" tables built from the data, and optional
// background (shown collapsed). Policy text never contains the practice's dollar amounts; the app adds those.
const FR_2027='https://public-inspection.federalregister.gov/2026-22743.pdf',CRS='https://www.everycrsreport.com/files/2023-11-14_R45106_736e9d27525242025e3ec29fb6254356108dd30f.html';
const APCM_LABEL={G0556:'≤1 chronic condition',G0557:'2+ chronic conditions',G0558:'QMB + 2+ chronic conditions'};
const LABEL={'99212':'Est. level 2','99213':'Est. level 3','99214':'Est. level 4','99215':'Est. level 5','99202':'New level 2','99203':'New level 3','99204':'New level 4','99205':'New level 5'};
const r2=n=>Number(n).toFixed(2),r4=n=>Number(n).toFixed(4),usd=n=>'$'+Number(n).toFixed(2),pct=n=>(n>0?'+':n<0?'−':'')+Math.abs(n*100).toFixed(2)+'%';
const arrow=(a,b,f=r2)=>a===b?{text:f(b),changed:false}:{text:`${f(a)} → ${f(b)}`,changed:true};
const cfOf=(data,year,track)=>data.annual.find(r=>r.year===year&&r.track===track&&r.code==='99213').cf;
const trackOf=(state,year)=>state.qp&&year>=2026?'qp':'nonqp',r3=n=>Number(n).toFixed(3);
const ivOf=(data,y,t,c)=>data.intervals.filter(r=>r.year===y&&r.track===t&&r.code===c);
// RVUs payment used, day-weighted across a year's effective periods (one period in every RVU event year).
const paidRvu=(data,y,t,c)=>{const iv=ivOf(data,y,t,c);return iv.reduce((a,r)=>a+r.pricing_rvu*r.interval_days,0)/iv[0].year_days;};
// Two decimals unless the value has more precision (1997–1998 work-adjusted RVUs): then three, so RVUs × CF ≈ fee.
const rvuArrow=(a,b)=>{const fine=x=>Math.abs(x*100-Math.round(x*100))>1e-6;return arrow(a,b,fine(a)||fine(b)?r3:r2);};
const cfCell=(data,year,t,i)=>({...arrow(cfOf(data,year-1,t),cfOf(data,year,t),n=>usd4(n)),repeat:i>0});
const multiPeriod=(data,year,t)=>[year-1,year].some(y=>new Set(ivOf(data,y,t,'99213').map(r=>r.effective_start)).size>1)?'CF and fee are day-weighted averages; RVUs × CF may differ by a few cents.':null;
// Table builders. Each returns {caption, head, rows (cells are strings or {text,changed}), note?}.
const TABLES={
 // Fee per visit = total RVUs × CF. RVUs are the ones payment used (pricing_rvu): in work-adjusted years (1997–1998,
 // 2007–2008) that is work × factor + PE + MP, not the published total. Day-weighted when a year has several periods.
 // Each row reads as an equation; the CF repeats per row (muted after the first). Components go in a collapsed details.
 rvus(data,year,state){
  const t=trackOf(state,year),fee=(y,c)=>data.annual.find(r=>r.year===y&&r.track===t&&r.code===c).base_fee,pub=(y,c)=>data.rvus.find(r=>r.year===y&&r.code===c);
  const rows=CODES.map((code,i)=>[`${code}<small>${LABEL[code]}</small>`,rvuArrow(paidRvu(data,year-1,t,code),paidRvu(data,year,t,code)),cfCell(data,year,t,i),arrow(fee(year-1,code),fee(year,code),usd)]);
  const f=y=>pub(y,'99213').work_factor,work=[year-1,year].filter(y=>f(y)!==1).map(y=>`${y} RVUs are as paid, after the ${f(y)} work adjustment${f(year)===1?`, which ended in ${year}`:''}.`);
  const parts=[...work,multiPeriod(data,year,t),`Fees are national amounts before sequestration${year>=2026?`, at the ${t==='qp'?'QP':'non-QP'} CF`:''}. Unchanged values are greyed out.`].filter(Boolean);
  const components={summary:'RVU components (work, PE, MP)',head:['Code','Work','PE','MP','Total'],rows:CODES.map(code=>{const a=pub(year-1,code),b=pub(year,code);return [`${code}<small>${LABEL[code]}</small>`,arrow(a.work,b.work),arrow(a.pe,b.pe),arrow(a.mp,b.mp),arrow(a.total,b.total)];}),note:work.length?`Published RVUs. ${[year-1,year].filter(y=>f(y)!==1).map(y=>`${y} work RVUs are before the ${f(y)} adjustment`).join('; ')}.`:null};
  return {caption:`Total RVUs × CF = fee per visit, ${year-1} → ${year}`,head:['Code','Total RVUs|RVUs','× CF','= Fee per visit|= Fee'],rows,note:parts.join(' '),components};
 },
 cf(data,year){const tracks=year>=2026?[['nonqp','Non-QP'],['qp','QP']]:[['nonqp','All clinicians']];return {caption:`CF, ${year-1} → ${year} ($ per RVU)`,head:['',String(year-1),String(year),'Change'],rows:tracks.map(([t,l])=>{const a=cfOf(data,year-1,t),b=cfOf(data,year,t);return [l,usd4(a),usd4(b),{text:pct(b/a-1),changed:true}];})};},
 cfRun(data){const relief={2021:'3.75%',2022:'3.00%',2023:'2.50%',2024:'1.25%; 2.93% from Mar 9',2025:'None'},rows=[];for(let y=2021;y<=2025;y++){const a=cfOf(data,y,'nonqp'),p=cfOf(data,y-1,'nonqp');rows.push([String(y),usd4(a),{text:pct(a/p-1),changed:true},relief[y]]);}rows.push(['2021 → 2025','',{text:pct(cfOf(data,2025,'nonqp')/cfOf(data,2021,'nonqp')-1),changed:true},'']);return {caption:'CF by year ($ per RVU)',head:['Year','CF','Change from prior year','One-year increase from Congress included|One-year increase'],rows,note:'2024 is a day-weighted average of two rates: 32.7442 until March 8 and 33.2875 from March 9.'};},
 cfPeriods(data,year){const periods=y=>[...new Map(data.intervals.filter(r=>r.year===y&&r.track==='nonqp'&&r.code==='99213').map(r=>[r.effective_start,r])).values()];const rows=[];let prev=null;for(const y of [year-1,year])for(const r of periods(y)){const label=r.effective_start.endsWith('-01-01')&&r.effective_end.endsWith('-12-31')?String(y):`${new Date(r.effective_start+'T00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${new Date(r.effective_end+'T00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`;rows.push([label,usd4(r.cf),prev?{text:pct(r.cf/prev-1),changed:true}:'—']);prev=r.cf;}return {caption:'CF by period ($ per RVU)',head:['Period','CF','Change'],rows};},
 cfSteps(data){const step=(t,u)=>{const a=cfOf(data,2026,t),m=CF_2026_WITHOUT_ONE_YEAR_INCREASE[t],b=cfOf(data,2027,t);return [usd4(a),usd4(m),u,'× 0.9988',{text:usd4(b),changed:true}];};return {caption:'How the 2027 CF was set ($ per RVU)',head:['','2026','Without 2026’s 2.5%','2027 update','Budget neutrality','2027'],rows:[['Non-QP',...step('nonqp','× 1.0025')],['QP',...step('qp','× 1.0075')]],note:'CY 2027 final rule, Tables D-B1 and D-B2.'};},
 seq(data,year){const P={2013:[['Until March 31, 2013','0%','0%'],['From April 1, 2013','2%','1.6%']],2020:[['January 1 – April 30, 2020','2%','1.6%'],['May 1, 2020 – March 31, 2022','0% (paused)','0%']],2022:[['January 1 – March 31, 2022','0%','0%'],['April 1 – June 30, 2022','1%','0.8%'],['From July 1, 2022','2%','1.6%']]}[year];return {caption:'Sequestration cut by period',head:['Period','Cut to Medicare’s payment','Net cut to the allowed amount'],rows:P.map(r=>[r[0],{text:r[1],changed:true},{text:r[2],changed:true}]),note:`Medicare pays 80% of the allowed amount, so cutting its share 2% lowers the allowed amount by ${(2*MEDICARE_SHARE).toFixed(1)}%. The model averages ${year} by day: ${(SEQUESTRATION[year]*MEDICARE_SHARE*100).toFixed(2)}% for the year.`};},
 g2211(data,year,state){const t=state.qp&&year>=2026?'qp':'nonqp';return {caption:`G2211 with each visit, ${year}`,head:['Code','Visit fee','G2211 add-on','Add-on as % of visit'],rows:CODES.map(code=>{const a=data.annual.find(r=>r.year===year&&r.track===t&&r.code===code);return [`${code}<small>${LABEL[code]}</small>`,usd(a.base_fee),{text:usd(a.complexity_increment),changed:true},(a.complexity_increment/a.base_fee*100).toFixed(0)+'%'];}),note:'National amounts before sequestration. The add-on is the same at every level, so it is a larger share of lower-level visits.'};},
 b1b2(data,year,state){const t=state.qp?'qp':'nonqp';return {caption:`Complexity amount per visit, 2026 → 2027 (${t==='qp'?'QP':'non-QP'} rate)`,head:['Code','2026 G2211','2027 B1 (16%)','2027 B2 (32%)'],rows:CODES.map(code=>{const g=data.annual.find(r=>r.year===2026&&r.track===t&&r.code===code).complexity_increment;return [`${code}<small>${LABEL[code]}</small>`,usd(g),{text:usd(modifierIncrement(data,t,code,'B1')),changed:true},{text:usd(modifierIncrement(data,t,code,'B2')),changed:true}];}),note:'National amounts before sequestration. B2 requires MSSP or LEAD ACO participation.'};},
 apcm(data,year,state){if(!data.apcm)return null;const t=state.qp?'qp':'nonqp',L=APCM_LABEL;return {caption:`APCM payment per patient per month (${t==='qp'?'QP':'non-QP'} rate from 2026)`,head:['Code','2025','2026','2027'],rows:APCM_CODES.map(c=>[`${c}<small>${L[c]}</small>`,...[2025,2026,2027].map(y=>({text:usd(apcmFee(data,c,y,cfOf(data,y,t))),changed:y===2025}))]),note:'National amounts before sequestration; the 20% patient share is included.'};},
};
// APCM RVUs revalued alongside office visits (2025 → 2026 → 2027). Shown in the RVU panels whether or not APCM patients
// are entered; the payment uses the selected track's conversion factor (QP or non-QP from 2026).
TABLES.apcmRvus=(data,year,state)=>{if(!data.apcm||year-1<APCM_START)return null;const t=trackOf(state,year),rv=(y,c)=>data.apcm.rvus.find(r=>r.year===y&&r.code===c);
 const rows=APCM_CODES.map((c,i)=>{const a=rv(year-1,c),b=rv(year,c);return [`${c}<small>${APCM_LABEL[c]}</small>`,rvuArrow(a.nf_total_rvu,b.nf_total_rvu),cfCell(data,year,t,i),arrow(apcmFee(data,c,year-1,cfOf(data,year-1,t)),apcmFee(data,c,year,cfOf(data,year,t)),usd)];});
 const components={summary:'RVU components (work, PE, MP)',head:['Code','Work','PE','MP','Total'],rows:APCM_CODES.map(c=>{const a=rv(year-1,c),b=rv(year,c);return [`${c}<small>${APCM_LABEL[c]}</small>`,arrow(a.work_rvu,b.work_rvu),arrow(a.nf_pe_rvu,b.nf_pe_rvu),arrow(a.mp_rvu,b.mp_rvu),arrow(a.nf_total_rvu,b.nf_total_rvu)];}),note:null};
 return {caption:`APCM: total RVUs × CF = payment per patient per month, ${year-1} → ${year}`,head:['Code','Total RVUs|RVUs','× CF','= Per patient per month|= Per month'],rows,note:`Billed once per patient per month. National amounts before sequestration, at the ${t==='qp'?'QP':'non-QP'} CF; the 20% patient share is included.`,components};};
const usd4=n=>'$'+r4(n);
const POLICIES={
 1997:{title:'Work RVUs for E/M visits raised, with an offset',summary:'The first five-year review raised work RVUs for most office E/M visits, offset by a 0.917 work adjustment that kept total Medicare spending unchanged.',tables:['rvus'],background:['HCFA reviews RVUs every five years. To keep spending level, the 0.917 multiplier scaled every work RVU down about 8%.'],url:'https://www.govinfo.gov/content/pkg/FR-1996-11-22/pdf/96-29558.pdf'},
 1999:{title:'PE RVUs start moving to actual resource costs',summary:'PE RVUs started shifting from historical charges to the resources actually used.',tables:['cf','rvus'],background:['The 1999 blend was 75% charge-based and 25% resource-based, reaching 100% resource-based in 2002. The separate work adjustment also ended in 1999.','Removing the separate work adjustment raised RVUs, so the CF was cut 8.3% to offset it (net −5.3% after the 2.3% update).'],url:'https://www.govinfo.gov/content/pkg/FR-1998-11-02/pdf/98-29181.pdf'},
 2007:{title:'Work RVUs for E/M visits raised, with an offset',summary:'The five-year review raised work RVUs for most E/M visits (99213–99215, 99204, 99205), offset by a 0.8994 work adjustment that kept spending unchanged.',tables:['rvus'],background:['The adjustment reduced work RVUs only, not PE or MP RVUs. In 2009 it moved into the CF.'],url:'https://www.govinfo.gov/content/pkg/FR-2006-12-01/pdf/06-9086.pdf'},
 '2009-rate':{title:'Work adjustment folded into the CF',summary:'The 0.8806 work adjustment came off the RVUs and was folded into a lower CF; fees for most visits rose slightly.',tables:['cf','rvus'],background:['From 2007 to 2008 CMS kept budget neutrality by scaling work RVUs down (× 0.8994, then × 0.8806). From 2009 the same effect came through the CF instead, which applies to all RVUs. The 2009 update under MIPPA was +1.1%.','Required by MIPPA section 133(b).'],url:'https://www.govinfo.gov/content/pkg/FR-2008-11-19/pdf/E8-26213.pdf'},
 '2015-rate':{title:'SGR repealed by MACRA',summary:'MACRA repealed the SGR formula and the 21% cut it had scheduled, and set a 0.5% increase from July 1, 2015.',tables:['cfPeriods'],background:['The SGR formula had produced large scheduled cuts that Congress overrode almost every year. MACRA, signed April 16, 2015, replaced it with fixed updates: +0.5% a year from July 2015 through 2019, then 0% through 2025, and from 2026 separate QP and non-QP updates.'],url:'https://www.congress.gov/bill/114th-congress/house-bill/2'},
 '2021-rate':{title:'CF cut for budget neutrality',summary:'Because the E/M increase was budget neutral, the CF fell for all services; a one-year 3.75% increase from Congress softened the cut.',tables:['cf'],background:['CMS first set the 2021 CF at 32.4085, a 10.2% cut. The CAA 2021 added 3.75% for 2021 and delayed G2211 payment to 2024, which reduced the offset needed; the final CF was 34.8931 (−3.3%). Smaller one-year increases followed in 2022–2024 (see 2025).'],url:'https://www.congress.gov/bill/116th-congress/house-bill/133'},
 '2013-sequestration':{title:'2% sequestration begins',summary:'From April 1, 2013, Medicare’s 80% share of each payment is cut 2%. The patient’s 20% share is not cut.',tables:['seq'],background:['Required by the Budget Control Act of 2011 and extended repeatedly, now through fiscal year 2032.'],url:CRS},
 '2020-sequestration':{title:'Sequestration paused',summary:'The 2% cut was suspended from May 1, 2020, during COVID-19, and stayed off through March 2022.',tables:['seq'],background:['Suspended by the CARES Act and extended by later laws. No sequestration applied in all of 2021.'],url:CRS},
 '2022-sequestration':{title:'Sequestration returns',summary:'The cut came back as 1% in April 2022 and the full 2% from July 2022.',tables:['seq'],background:['Set by the Protecting Medicare and American Farmers from Sequester Cuts Act. The full 2% has applied since July 2022 and continues under current law.'],url:CRS},
 2021:{title:'Office E/M visits revalued',summary:'RVUs rose substantially for every office E/M level except new-patient level 2 (99202), and levels could now be chosen by medical decision-making or total time.',tables:['rvus'],background:['History and examination no longer determined the visit level. Because the change had to be budget neutral, the CF was cut for all services; see the 2021 CF event.'],url:'https://www.cms.gov/sites/default/files/2022-01/Physician_Fee_Schedule__PFS__Payment_for_OfficeOutpatient_Evaluation_and_Management__EM__Visits.pdf'},
 2024:{title:'G2211 add-on begins',summary:'G2211 became payable as a fixed add-on to office E/M visits for ongoing or complex care.',tables:['g2211'],background:['It recognizes being the continuing focal point for a patient’s care, or managing a serious or complex condition over time. It could be added to new and established visits.'],url:'https://www.cms.gov/files/document/mm13473-how-use-office-and-outpatient-evaluation-and-management-visit-complexity-add-code-g2211.pdf'},
 '2025-apcm':{title:'APCM codes begin',summary:'APCM pays a set amount per enrolled patient per month, from January 2025.',tables:['apcm'],background:['The level depends on the patient: G0556 for one or fewer chronic conditions, G0557 for two or more, G0558 for a QMB with two or more. Billed once per patient per month; consent is required and the 20% coinsurance generally applies.'],url:'https://www.cms.gov/medicare/payment/fee-schedules/physician-fee-schedule/advanced-primary-care-management-services'},
 2025:{title:'CF cut, fifth year in a row',summary:'The CF fell every year from 2021 to 2025.',tables:['cfRun'],background:['One-year increases from Congress for 2021–2024 offset part of the cuts; none carried into 2025. Budget-neutrality offsets for the 2021 E/M revaluation and for G2211 also lowered the CF.'],url:'https://www.cms.gov/files/document/cms-1807-f.pdf'},
 2026:{title:'CF up; office PE RVUs up',summary:'The CF rose, including a one-year 2.5% increase from Congress, and PE RVUs for office E/M visits rose.',tables:['cf','rvus','apcmRvus'],background:['QPs and non-QPs got different CFs for the first time. CMS began recognizing greater indirect PE for office-based than for facility-based practitioners. Office E/M visits were exempt from the new 2.5% efficiency cut to work RVUs.'],url:'https://www.cms.gov/newsroom/fact-sheets/calendar-year-cy-2026-medicare-physician-fee-schedule-final-rule-cms-1832-f'},
 '2027-rvu':{title:'Office PE RVUs down',summary:'PE RVUs fell for most office E/M codes; work RVUs did not change.',tables:['rvus','apcmRvus'],background:['CMS changed how indirect PE is spread across services, and office E/M visits now receive less of it.'],url:FR_2027},
 '2027-rate':{title:'2026’s one-year 2.5% increase ends',summary:'The CF drops because 2026’s one-year increase ends. The 2027 update itself is slightly positive.',tables:['cfSteps'],background:['The 2.5% increase applied to 2026 only, by statute. The 2027 update is +0.25% for non-QPs and +0.75% for QPs, with a −0.12% budget-neutrality adjustment.'],url:FR_2027},
 2027:{title:'B1 and B2 replace G2211',summary:'The fixed G2211 add-on is replaced by modifiers worth 16% (B1) or 32% (B2) of the visit’s full fee. B2 requires being in an MSSP or LEAD ACO.',tables:['b1b2'],background:['The CY 2027 final rule sets B1 at 16 percent of the total RVUs of the E/M service on the claim. B2, at 32 percent, is limited to clinicians in MSSP or LEAD ACOs; it does not depend on QP status.'],url:FR_2027},
};
// Short hover lines for each table type: the key numbers only. RVU events show the mix-weighted average total RVUs
// per visit (as paid) and the two most-used codes, plus the CF when the event has no CF table; the full tables are in the details panel.
const topCodes=(state,n)=>[...CODES].filter(c=>state.mix[c]>0).sort((a,b)=>state.mix[b]-state.mix[a]||CODES.indexOf(a)-CODES.indexOf(b)).slice(0,n);
const pct1=n=>(n>0.0005?'+':n<-0.0005?'−':'')+Math.abs(n*100).toFixed(1)+'%',chg=(a,b)=>a?` (${pct1(b/a-1)})`:'';
const HOVER={
 rvus(data,year,state){const tr=trackOf(state,year),tot=(y,c)=>paidRvu(data,y,tr,c),avg=y=>CODES.reduce((a,c)=>a+state.mix[c]/100*tot(y,c),0),a=avg(year-1),b=avg(year);return [`Avg total RVUs per visit (selected mix): ${r2(a)} → ${r2(b)}${chg(a,b)}`,...topCodes(state,2).map(c=>`${c}: ${r2(tot(year-1,c))} → ${r2(tot(year,c))}${chg(tot(year-1,c),tot(year,c))}`)];},
 cf(data,year,state){const t=state.qp&&year>=2026?'qp':'nonqp',a=cfOf(data,year-1,t),b=cfOf(data,year,t);return [`CF${year>=2026?(t==='qp'?' (QP)':' (non-QP)'):''}: ${usd4(a)} → ${usd4(b)}${chg(a,b)}`];},
 cfRun(data){const a=cfOf(data,2024,'nonqp'),b=cfOf(data,2025,'nonqp');return [`CF: ${usd4(a)} → ${usd4(b)}${chg(a,b)}`,`Since 2021: ${pct1(b/cfOf(data,2021,'nonqp')-1)}`];},
 cfSteps(data,year,state){const t=state.qp?'qp':'nonqp';return [`CF${t==='qp'?' (QP)':' (non-QP)'}: ${usd4(cfOf(data,2026,t))} → ${usd4(cfOf(data,2027,t))}`,`Without 2026’s 2.5%: ${usd4(CF_2026_WITHOUT_ONE_YEAR_INCREASE[t])}, then the 2027 update`];},
 cfPeriods(){return ['CF: $35.7547 → $35.9335 from July 1 (+0.5%)','The SGR’s scheduled 21% cut never took effect'];},
 seq(data,year){return [{2013:'Cut to the allowed amount: 0% → 1.6% from April 1',2020:'Cut to the allowed amount: 1.6% → 0% from May 1',2022:'Cut to the allowed amount: 0% → 0.8% in April → 1.6% in July'}[year]];},
 g2211(data,year,state){const c=topCodes(state,1)[0];if(!c)return [];const a=data.annual.find(r=>r.year===year&&r.track==='nonqp'&&r.code===c);return [`${c}: ${usd(a.base_fee)} visit + ${usd(a.complexity_increment)} G2211 (${(a.complexity_increment/a.base_fee*100).toFixed(0)}%)`];},
 b1b2(data,year,state){const c=topCodes(state,1)[0];if(!c)return [];const t=state.qp?'qp':'nonqp',m=state.program==='aco'?'B2':'B1';return [`${c}: G2211 ${usd(data.annual.find(r=>r.year===2026&&r.track===t&&r.code===c).complexity_increment)} → ${m} ${usd(modifierIncrement(data,t,c,m))} per visit`];},
 // APCM RVU rows only when APCM patients are entered (the most-billed level); the full table is in the panel.
 apcmRvus(data,year,state){if(!data.apcm||year-1<APCM_START||!APCM_CODES.some(c=>state.apcm?.[c]>0))return [];const c=APCM_CODES.reduce((a,c)=>state.apcm[c]>state.apcm[a]?c:a),t=r=>data.apcm.rvus.find(x=>x.year===r&&x.code===c).nf_total_rvu;return [`APCM ${c} total RVUs: ${r2(t(year-1))} → ${r2(t(year))}${chg(t(year-1),t(year))}`];},
 apcm(data,year,state){if(!data.apcm)return [];const c=APCM_CODES.reduce((a,c)=>state.apcm?.[c]>(state.apcm?.[a]??0)?c:a,'G0557');return [`${c}: ${usd(apcmFee(data,c,2025,cfOf(data,2025,'nonqp')))} per patient per month`];},
};
export function eventHover(data,state,key){const policy=POLICIES[key];if(!policy)return null;const year=parseInt(key,10),lines=policy.tables.flatMap(t=>t==='rvus'&&!policy.tables.includes('cf')?[...HOVER.rvus(data,year,state),...HOVER.cf(data,year,state)]:HOVER[t](data,year,state));return {lines,more:policy.tables.includes('rvus')?'Click the marker for all 8 codes':'Click the marker for the full table'};}
export function policyFor(data,state,key){const policy=POLICIES[key];if(!policy)return null;const year=parseInt(key,10);const tables=policy.tables.map(t=>TABLES[t](data,year,state)).filter(Boolean);return {...policy,year,tables};}
export const POLICY_KEYS=Object.keys(POLICIES);
